SELECT machine_id AS peer_id, service_id, machine_label, access_client_id, credential_hash, state, expires_at, last_seen_at AS last_seen, last_revocation_operation_id AS last_revocation_operation, last_enrollment_operation_id AS last_enrollment_operation, created_at, updated_at FROM machine_enrollments WHERE service_id = ? OR access_client_id = ? OR credential_hash = ? OR machine_id = ?;
